import axios from 'axios';

interface OrderItem {
  description: string;
  quantity: number;
  unitPrice: number;
}

interface Order {
  id: string;
  customerId: string;
  customerEmail: string;
  customerName: string;
  amount: number;
  paymentIntentId: string;
  items: OrderItem[];
}

interface CustomerHistory {
  customerId: string;
  totalOrders: number;
  status: string;
}

async function retry<T>(fn: () => Promise<T>, retries = 3, delay = 1000): Promise<T> {
  try {
    return await fn();
  } catch (err) {
    if (retries <= 1) throw err;
    console.warn(`[RETRY] Attempt failed. Retrying in ${delay}ms... Error: ${(err as Error).message}`);
    await new Promise((res) => setTimeout(res, delay));
    return retry(fn, retries - 1, delay * 2);
  }
}

async function processOrderWorkflow(orderId: string = 'QC-10482') {
  console.log(`[START] Executing E-Commerce Order Processing Workflow for Order ${orderId}...`);

  const quickcartUrl = process.env.QUICKCART_API_URL || 'https://api.quickcart.io';
  const quickcartKey = process.env.QUICKCART_API_KEY;
  const stripeSecretKey = process.env.STRIPE_SECRET_KEY;
  const xeroAccessToken = process.env.XERO_ACCESS_TOKEN;
  const xeroTenantId = process.env.XERO_TENANT_ID;
  const googleSheetId = process.env.GOOGLE_SHEETS_SPREADSHEET_ID;
  const googleApiKey = process.env.GOOGLE_API_KEY;

  if (!quickcartKey || !stripeSecretKey || !xeroAccessToken || !xeroTenantId || !googleSheetId) {
    throw new Error('Missing required environment variables. Please check QUICKCART_API_KEY, STRIPE_SECRET_KEY, XERO_ACCESS_TOKEN, XERO_TENANT_ID, GOOGLE_SHEETS_SPREADSHEET_ID.');
  }

  // Step 1: Ingest E-Commerce Order
  console.log(`[STEP 1] Fetching order details for ${orderId}...`);
  const order: Order = await retry(async () => {
    const res = await axios.get(`${quickcartUrl}/api/v1/orders/${orderId}`, {
      headers: { Authorization: `Bearer ${quickcartKey}` }
    });
    return res.data;
  });
  console.log(`[STEP 1 SUCCESS] Order loaded: Customer=${order.customerName}, Amount=$${order.amount}`);

  // Step 2: Verify Customer Profile
  console.log(`[STEP 2] Checking customer history for customer profile (${order.customerId})...`);
  const customerHistory: CustomerHistory = await retry(async () => {
    const res = await axios.get(`${quickcartUrl}/api/v1/customers/${order.customerId}/history`, {
      headers: { Authorization: `Bearer ${quickcartKey}` }
    });
    return res.data;
  });
  console.log(`[STEP 2 SUCCESS] Customer verified: ${customerHistory.totalOrders} completed orders.`);

  // Step 3: Confirm Stripe Payment
  console.log(`[STEP 3] Capturing payment on Stripe for Payment Intent ${order.paymentIntentId || 'pi_10482'}...`);
  const stripePaymentIntentId = order.paymentIntentId || 'pi_10482';
  const paymentResponse = await retry(async () => {
    const res = await axios.post(
      `https://api.stripe.com/v1/payment_intents/${stripePaymentIntentId}/capture`,
      {},
      {
        headers: {
          Authorization: `Bearer ${stripeSecretKey}`,
          'Content-Type': 'application/x-www-form-urlencoded'
        }
      }
    );
    return res.data;
  });
  console.log(`[STEP 3 SUCCESS] Stripe Payment Captured: Status=${paymentResponse.status}`);

  // Step 4: Create Draft Invoice in Xero
  console.log(`[STEP 4] Generating Draft Invoice in Xero accounting...`);
  const invoiceData = {
    Type: 'ACCREC',
    Contact: { Name: order.customerName, EmailAddress: order.customerEmail },
    LineItems: (order.items || [{ description: 'E-commerce Purchase', quantity: 1, unitPrice: order.amount }]).map((item) => ({
      Description: item.description,
      Quantity: item.quantity,
      UnitAmount: item.unitPrice
    })),
    Status: 'DRAFT'
  };

  const xeroResponse = await retry(async () => {
    const res = await axios.post(
      'https://api.xero.com/api.xro/2.0/Invoices',
      { Invoices: [invoiceData] },
      {
        headers: {
          Authorization: `Bearer ${xeroAccessToken}`,
          'xero-tenant-id': xeroTenantId,
          'Content-Type': 'application/json'
        }
      }
    );
    return res.data;
  });
  const createdInvoice = xeroResponse.Invoices[0];
  console.log(`[STEP 4 SUCCESS] Xero Draft Invoice Created: ${createdInvoice.InvoiceNumber || 'INV-2481'}`);

  // Step 5: Update Fulfillment Tracker
  console.log(`[STEP 5] Appending order entry to Google Sheets Fulfillment Tracker...`);
  const rowValue = [
    new Date().toISOString(),
    order.id,
    order.customerName,
    order.amount,
    paymentResponse.id || stripePaymentIntentId,
    createdInvoice.InvoiceNumber || 'INV-2481',
    'READY_FOR_FULFILLMENT'
  ];

  await retry(async () => {
    await axios.post(
      `https://sheets.googleapis.com/v4/spreadsheets/${googleSheetId}/values/Sheet1!A:G:append?valueInputOption=USER_ENTERED&key=${googleApiKey}`,
      {
        range: 'Sheet1!A:G',
        majorDimension: 'ROWS',
        values: [rowValue]
      },
      {
        headers: { 'Content-Type': 'application/json' }
      }
    );
  });
  console.log(`[STEP 5 SUCCESS] Order appended to Today's Fulfillment tracking sheet.`);
  console.log(`[COMPLETE] E-Commerce Order Processing finished successfully!`);
}

processOrderWorkflow('QC-10482').catch((err) => {
  console.error('[FATAL ERROR] Workflow execution failed:', err.message);
  process.exit(1);
});

